import{_ as l,H as t,f as n,b as e,j as r}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"Q63 | 方向：AI应用领域创业","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q63｜方向：AI应用领域创业.md","filePath":"致程序员：AI百问百答/Q63｜方向：AI应用领域创业.md","lastUpdated":1795559851000}'),s={name:"致程序员：AI百问百答/Q63｜方向：AI应用领域创业.md"};function o(p,a,_,i,A,d){return t(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"q63-方向-ai应用领域创业",tabindex:"-1"},[r("Q63 | 方向：AI应用领域创业 "),e("a",{class:"header-anchor",href:"#q63-方向-ai应用领域创业","aria-label":'Permalink to "Q63 | 方向：AI应用领域创业"'},"​")],-1),e("ul",null,[e("li",null,"作者介绍：月影，波波熊科技联合创始人")],-1),e("p",null,"Q：如果想在 AI 领域做一些创业尝试，您有什么建议，需要注意哪些风险？",-1),e("p",null,"月影：AI 领域创业其实细分挺多领域的，比如做大模型的，做数据的、做应用和工具的，还有做内容的和做培训咨询的。我这一年多时间里， 更专注于 AI 应用和工具的方向。我自身的感受是，AI 处在一个快速发展变革的时期，它的底层技术、模型能力发展很快，而且它正在从本质上颠覆许多行业的底层逻辑和工作模式，这里面肯定是带来了很多潜在机会。",-1),e("p",null,"但是，从另一方面来说，AI 太新了，而且发展太快，现在正处在一 个让很多普通人觉得有点茫然和无所适从的阶段。从应用本身的发展角度来讲，如果主要用户处在比较茫然的适应期阶段，实际上是很难真正挖掘出本质需求，为用户打造出一款真正的 killer App 的， 主要是用户自己可能也还没想明白。",-1),e("p",null,"因此目前 AI 应用领域的创业，我认为真正难的是挖掘需求。我们现在看到的很多工具，做出的东西看起来很美好，但实际上用起来往往“也就那样”，这其实不是工具不好，不是开发者能力问题，更多的问题还是需求本身并没有明确。",-1),e("p",null,"所以对于 AI 应用领域的创业者和独立开发者，我的建议是耐心一点，多研究产品和技术，多看多想，不急于“造轮子”，保持敏锐的洞察力，随着时间推演，终有一天你会找到属于自己的大机会。另外，你可以像我们一样，从小处做起，先做社群，找到潜在用户群体，多组织和参与活动，和大家深入聊，先不做“大而强”，从“小而美”做起，做好内容和服务，让公司先活下来，然后再等待机会就可以了。",-1)])])}const u=l(s,[["render",o]]);export{c as __pageData,u as default};
